    yield '\n\n    if CHECK_BLOCK_BOUNDARY:\n        # Mask out the elements that are out of the KV_LEN for non divisible seqlen.\n        post_mod_scores = tl.where(offs_n < KV_LEN, post_mod_scores, float("-inf"))\n\n    if not IS_FULL_BLOCKS:\n        '
    yield str(t_1(context.call((undefined(name='modification') if l_0_modification is missing else l_0_modification), subgraph_number=1, output_name='mask_mod_output', score='qk', b='off_z', h='off_h', m='m', n='n'), 2))
    yield '\n\n        if CHECK_BLOCK_BOUNDARY:\n            mask_mod_output = tl.where(offs_n < KV_LEN, mask_mod_output, False)\n        # apply mask for partially unmasked blocks\n        post_mod_scores = tl.where(mask_mod_output, post_mod_scores, float("-inf"))\n\n    if not PRESCALE_QK:\n        post_mod_scores *= RCP_LN2\n    # ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n    # -- compute scaling constant ---\n    m_ij = tl.maximum(m_i, tl.max(post_mod_scores, 1))\n    if not ROWS_GUARANTEED_SAFE:\n        masked_out_rows = (m_ij == float("-inf"))\n        m_ij_masked = tl.where(masked_out_rows, 0, m_ij)\n    else:\n        m_ij_masked = m_ij\n\n    alpha = tl.math.exp2(m_i - m_ij_masked)\n    p = tl.math.exp2(post_mod_scores - m_ij_masked[:, None])\n\n    # NB: l_i update is pulled up here since it\'s a bit faster\n    # NB: For headdim=256, it\'s faster to move it back down to after m_i =\n    # m_ij\n    l_i = l_i * alpha + tl.sum(p, 1)\n    # # -- scale and update acc --\n    acc = acc * alpha[:, None]\n    v = load_checked_block(V_block_ptr, IS_DIVISIBLE, SAFE_HEAD_DIM)\n    acc = tl.dot(p.to(MATMUL_PRECISION), v, acc, input_precision=FLOAT32_PRECISION)\n\n    # -- update m_i\n    m_i = m_ij\n\n    return acc, l_i, m_i\n'

